/** Fallback — generic agent icon for unknown custom agents. */
function DefaultIcon({ className }: IconProps) {
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <rect x="4" y="2" width="16" height="13" rx="3" />
      <line x1="9" y1="15" x2="9" y2="21" />
      <line x1="15" y1="15" x2="15" y2="21" />
      <line x1="6" y1="21" x2="18" y2="21" />
      <circle cx="9" cy="8" r="1.2" fill="currentColor" stroke="none" />
      <circle cx="15" cy="8" r="1.2" fill="currentColor" stroke="none" />
    </svg>
  );
}

/**
 * Brand mark for a local ACP agent, by registry id.
 *
 * Shared by the settings tab and the chat transcript so a turn produced by an
 * external agent is marked with that agent rather than with Suzent's robot.
 */
export function AcpAgentIcon({
  id,
  className = 'w-5 h-5 shrink-0',
}: {
  id?: string;
  className?: string;
}) {
  if (id === 'claude-code' || id === 'claude-acp') return <ClaudeIcon className={className} />;
  if (id === 'claude-code-api') return <ClaudeIcon className={className} api />;
  if (id === 'codex' || id === 'codex-acp') return <OpenAIIcon className={className} />;
  if (id === 'hermes') return <HermesIcon className={className} />;
  if (id === 'openclaw') return <OpenClawIcon className={className} />;
  if (id === 'gemini') return <GeminiIcon className={className} />;
  if (id === 'github-copilot-cli') return <CopilotIcon className={className} />;
  if (id === 'qwen-code') return <QwenIcon className={className} />;
  if (id === 'kimi-code' || id === 'kimi') return <KimiIcon className={className} />;
  if (id === 'grok' || id === 'grok-build') return <GrokIcon className={className} />;
  if (id === 'opencode' || id === 'opencode-v2') return <OpenCodeIcon className={className} />;
  if (id === 'cursor') return <CursorIcon className={className} />;
  if (id === 'cline') return <ClineIcon className={className} />;
  if (id === 'goose') return <GooseIcon className={className} />;
  if (id === 'auggie') return <AuggieIcon className={className} />;
  if (id === 'kilo') return <KiloIcon className={className} />;
  return <DefaultIcon className={className} />;
}
